// Load system prompt placeholder
const systemPrompt = `Ты — стратег по контенту для ресторана "Hungry Club" в Ялте.
Твоя задача — составить контент-план на 14 дней.

## Контекст бренда

**Кто мы:** Сервис доставки еды ресторанного качества. Более 16 категорий блюд.
**Tone of Voice:** на «ты», дружелюбно-энергичный. Короткие фразы. Эмодзи приветствуются.
**Табу:** не используем «вкусно», «уютная атмосфера», «команда профессионалов».
**Флагманы:** Бургер фирменный (680₽), Трюфельный (760₽), Камамбер и груша (750₽).

## ЖЁСТКИЕ ПРАВИЛА
1. Каждый день: 1 пост + 1–3 сторис. Рилс — 2 раза в неделю.
2. 40% еда, 20% атмосфера, 20% люди, 10% сторителлинг, 10% акции.
3. Учитывай погоду: жарко → лимонады и доставка на пляж; дождливо → супы и уют.
4. Учитывай iiko: что продаётся → пушим; что заканчивается → НЕ пушим.
5. Учитывай праздники из календаря.
6. Не повторяй темы из последних 20 постов.

ВЫХОД — строго JSON:
{
  "plan_summary": "...",
  "items": [
    {
      "date": "2026-05-15",
      "format": "post" | "reel" | "story",
      "topic": "...",
      "goal": "promo" | "awareness" | "engagement",
      "rationale": "...",
      "key_message": "...",
      "suggested_visual": "...",
      "menu_item_hint": "..."
    }
  ]
}`;

const context = $input.first().json.body;

// Build user prompt from context
const userPrompt = `## ЗАДАЧА

Составь контент-план для ресторана ${context.restaurant_name || 'Hungry Club'} (${context.restaurant_city || 'Ялта'}) на период ${context.period_start} – ${context.period_end} (14 дней).

## ДАННЫЕ ДЛЯ РАБОТЫ

### 1. Brand Guidelines
${JSON.stringify(context.brand_guidelines, null, 2)}

### 2. Прогноз погоды
${JSON.stringify(context.weather, null, 2)}

### 3. iiko-инсайты
${context.iiko_insights || 'Нет данных iiko.'}

### 4. Календарь праздников
${JSON.stringify(context.holidays, null, 2)}

### 5. Последние 20 постов (не повторять!)
${JSON.stringify(context.recent_posts, null, 2)}

${context.user_feedback ? '## ПРАВКИ ОТ УПРАВЛЯЮЩЕГО\n\n' + context.user_feedback : ''}`;

return {
  system_prompt: systemPrompt,
  user_prompt: userPrompt,
  context: context
};

const response = $input.first().json;
const content = response.choices[0].message.content;

// Strip markdown fences if present
let jsonStr = content;
jsonStr = jsonStr.replace(/```json\n?/g, '').replace(/```/g, '').trim();

let plan;
try {
  plan = JSON.parse(jsonStr);
} catch (e) {
  return { error: 'JSON parse failed', raw: content };
}

// Cost calculation: Claude Sonnet 4.5 = $3/M input, $15/M output
const inputCost = (response.usage.prompt_tokens / 1000000) * 3;
const outputCost = (response.usage.completion_tokens / 1000000) * 15;

return {
  plan: plan,
  meta: {
    model: response.model,
    prompt_tokens: response.usage.prompt_tokens,
    completion_tokens: response.usage.completion_tokens,
    total_tokens: response.usage.total_tokens,
    cost_usd: (inputCost + outputCost).toFixed(4),
    plan_items: plan.items?.length || 0
  }
};

const items = $node['code-parse'].json.plan.items || [];
const restaurantId = $node['code-parse'].json.context.restaurant_id;
const planId = $node['Supabase: Insert Plan'].json[0].id;

const queries = items.map(item => {
  return `INSERT INTO content_items (
  plan_id, restaurant_id, scheduled_date, format, topic, goal, status
) VALUES (
  '${planId}',
  '${restaurantId}',
  '${item.date}',
  '${item.format}',
  '${escapeSql(item.topic)}',
  '${item.goal}',
  'planned'
)`;
});

function escapeSql(str) {
  return (str || '').replace(/'/g, "''");
}

return { queries: queries, planId: planId };
